@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');
:root{--ink:#0e1010;--panel:#171a19;--panel2:#1d211f;--line:#303632;--muted:#878f86;--paper:#e8e8d9;--moss:#a6bd82;--acid:#c0d897;--red:#bd736b;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',serif}
*{box-sizing:border-box}body{margin:0;background:#0b0d0d;color:var(--paper);font-family:var(--sans);min-height:100vh;display:flex;justify-content:center;align-items:flex-start;padding:24px 20px;overflow-x:hidden}.game-shell{width:min(1200px,100%);background:var(--ink);border:1px solid #292e2a;box-shadow:0 24px 90px #0009}.topbar{height:68px;display:flex;align-items:center;padding:0 24px;border-bottom:1px solid var(--line);gap:13px}.brand-mark{width:32px;height:32px;border:1px solid #54634c;color:var(--acid);display:grid;place-items:center;font-size:18px}.brand{display:flex;flex-direction:column;gap:3px}.brand strong{letter-spacing:2px;font:500 13px var(--mono)}.brand span,.chapter,.sound-toggle{font:10px var(--mono);letter-spacing:1.5px;color:#8f988c}.chapter{margin:auto;display:flex;align-items:center;gap:10px}.chapter i,.alive-dot,.save-dot{width:6px;height:6px;background:#a5c67f;display:inline-block;border-radius:50%;box-shadow:0 0 9px #a5c67f88}.chapter span{color:#4d554c}.sound-toggle{background:transparent;color:var(--acid);border:1px solid var(--line);padding:8px 11px;cursor:pointer}.sound-toggle span{font-size:9px;color:var(--muted)}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:0;min-height:0}.viewport-wrap{padding:20px 20px 0;min-width:0}.viewport{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;background:#101914;border:1px solid #343a32}.viewport canvas{display:block;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 50%,transparent 42%,#05080666 100%);box-shadow:inset 0 0 70px #080b08aa}.underbar{height:35px;display:flex;align-items:center;justify-content:space-between;color:#899086;font:9px var(--mono);letter-spacing:1px}.keycap{font:9px var(--mono);font-style:normal;padding:3px 5px;border:1px solid #41483f;color:#c1c6b5;margin-left:10px;margin-right:3px}.coordinate{color:#5d675c}.sidebar{border-left:1px solid var(--line);padding:21px 20px 16px;display:flex;flex-direction:column}.side-heading{font:10px var(--mono);letter-spacing:1.3px;color:#bdc2b5;display:flex;justify-content:space-between;align-items:center}.side-heading .alive-dot{width:5px;height:5px}.companion-card{display:flex;gap:13px;margin:17px 0 19px}.companion-portrait{height:86px;width:78px;background:linear-gradient(145deg,#29352d,#151b17);border:1px solid #414c3c;position:relative;display:grid;place-items:center;overflow:hidden}.companion-portrait:before,.companion-portrait:after{content:'';position:absolute;width:60px;height:30px;border:1px solid #55664b;transform:rotate(-30deg);opacity:.5}.companion-portrait:after{transform:rotate(30deg);width:45px}.portrait-glow{position:absolute;width:45px;height:45px;border-radius:50%;background:#c9e79533;filter:blur(15px)}.portrait-moth{color:#d8e7ae;font-size:31px;text-shadow:0 0 18px #d8e7ae}.companion-info{flex:1;min-width:0}.eyebrow{font:9px var(--mono);letter-spacing:1.1px;color:#9eb783}.companion-info h2{margin:4px 0 7px;font:700 19px var(--serif);color:#e3e3d4}.level-line{display:flex;justify-content:space-between;font:9px var(--mono);color:#abb1a3}.level-line b{color:var(--acid);font-weight:500}.level-line span+span{font-size:8px;letter-spacing:.5px;color:#84907d}.side-hp,.health-track,.ally-track{height:4px;background:#343a32;margin-top:8px;overflow:hidden}.side-hp i,.health-track i,.ally-track i{height:100%;width:100%;display:block;background:#a9c783;transition:width .25s}.companion-info>small{font:8px var(--mono);color:#80877d;display:block;margin-top:5px}.side-divider{height:1px;background:var(--line);margin:0 0 17px}.inventory-total,.notes-count{color:#889283;font:9px var(--mono)}.kit-row{display:flex;align-items:center;gap:10px;margin-top:13px}.kit-icon{width:30px;height:30px;display:grid;place-items:center;border:1px solid #41483f;font-size:18px}.snare-icon{color:#b4c992}.tonic-icon{color:#bd817b}.kit-row div{display:flex;flex-direction:column;gap:3px;flex:1}.kit-row b{font-size:11px;font-weight:500;color:#d4d7ca}.kit-row small{font-size:9px;color:#7f877c}.kit-row strong{font:11px var(--mono);color:#b8c5a5}.kit-row+.side-divider{margin-top:19px}.note-card{margin-top:13px;padding:12px 12px 10px;background:#1a1e1b;border:1px solid #30372f;position:relative}.note-pin{position:absolute;right:11px;top:7px;color:#8da378;font-size:13px}.note-card p{font:italic 12px/1.5 var(--serif);color:#bdc3b4;margin:0 14px 10px 0}.note-card small{font:8px var(--mono);letter-spacing:.4px;color:#788174}.sidebar-footer{margin-top:auto;padding-top:18px;display:flex;align-items:center;gap:7px;font:8px var(--mono);letter-spacing:.8px;color:#798174}.save-dot{width:5px;height:5px}.sidebar-footer button{margin-left:auto;background:none;border:0;color:#6b7568;font:8px var(--mono);letter-spacing:.8px;cursor:pointer;padding:5px}.sidebar-footer button:hover{color:var(--paper)}footer{height:39px;border-top:1px solid var(--line);padding:0 22px;display:flex;align-items:center;justify-content:space-between;color:#697166;font:8px var(--mono);letter-spacing:1.1px}footer b{color:#a7bf83;font-size:11px;margin-left:4px}
.location-label{position:absolute;left:16px;top:15px;display:flex;flex-direction:column;padding-left:13px;gap:3px;text-shadow:0 1px 5px #000}.location-dot{position:absolute;left:0;top:4px;width:5px;height:5px;background:var(--acid);border-radius:50%;box-shadow:0 0 8px var(--acid)}.location-label span:nth-child(2){font:9px var(--mono);letter-spacing:1.4px;color:#e0e2d4}.location-label small{font:8px var(--mono);letter-spacing:.8px;color:#9ca393}.objective{position:absolute;top:13px;right:14px;display:flex;align-items:center;gap:8px;padding:7px 9px;background:#111713c9;border:1px solid #465044;color:#d1d7c6}.objective-icon{font-size:16px;color:#c3d795}.objective>span:nth-child(2){display:flex;flex-direction:column;gap:3px}.objective small{font:7px var(--mono);letter-spacing:1.3px;color:#91a082}.objective b{font:9px var(--mono);font-weight:400}.objective i{font:9px var(--mono);font-style:normal;color:var(--acid);padding-left:6px;border-left:1px solid #394338}.toast{position:absolute;z-index:4;bottom:15px;left:50%;transform:translate(-50%,10px);background:#101612e8;border:1px solid #59644e;padding:9px 14px;color:#e3e6d8;font:10px var(--mono);letter-spacing:.4px;opacity:0;transition:.2s;white-space:nowrap;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.intro-card{position:absolute;inset:0;z-index:3;background:linear-gradient(90deg,#0d120feb,#111710ad 58%,#10161070);padding:9% 7%;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;transition:opacity .5s}.intro-card:after{content:'';position:absolute;right:10%;top:12%;width:27%;height:65%;border:1px solid #a9c78333;clip-path:polygon(47% 0,58% 19%,50% 38%,78% 53%,65% 100%,37% 76%,15% 100%,26% 53%,4% 29%,39% 27%);background:#99b26b0b;pointer-events:none}.intro-card.gone{opacity:0;pointer-events:none}.intro-card .eyebrow{font-size:8px;letter-spacing:1.8px;color:#b1c48f}.intro-card h1{font:700 clamp(25px,4.2vw,45px)/1.01 var(--serif);letter-spacing:1px;margin:13px 0;color:#e5e6d7}.intro-card h1 i{font-weight:700;color:#c1d69b}.intro-card p{font:12px/1.7 var(--mono);color:#a9b0a2;margin:0 0 19px}.intro-card button,.evolution button{border:1px solid #9aaf78;background:#9eb780;color:#11170f;padding:12px 15px;font:10px var(--mono);letter-spacing:1.2px;cursor:pointer}.intro-card button span,.evolution button span{margin-left:17px}.intro-card>small{font:8px var(--mono);letter-spacing:.8px;color:#8d9787;margin-top:14px}.battle{position:absolute;z-index:2;inset:0;background:linear-gradient(155deg,#111a18d9,#141914ef 65%,#0d100e);padding:15px 20px;display:flex;flex-direction:column;transition:opacity .2s}.battle.hidden,.evolution.hidden{display:none}.battle-topline{display:flex;justify-content:space-between;font:8px var(--mono);letter-spacing:1.4px;color:#b2c391;border-bottom:1px solid #444d3d;padding-bottom:8px}.battle-topline span+span{color:#858f80}.enemy-card{display:flex;align-items:center;justify-content:space-between;flex:1;padding:13px 8% 8px}.enemy-copy{min-width:145px}.enemy-copy .eyebrow{color:#bb8f81;font-size:8px}.enemy-copy strong{display:block;font:700 25px var(--serif);margin:5px 0 7px}.enemy-copy .health-track{width:145px;margin:0 0 5px;background:#3d3330}.enemy-copy .health-track i{background:#bd776b}.enemy-copy small{font:8px var(--mono);color:#a19e92}.battle-sprite{width:100px;height:84px;position:relative;filter:drop-shadow(0 0 16px #b19d6855)}.battle-sprite:before{content:'';position:absolute;inset:8px 20px;background:#4b5e4d;clip-path:polygon(40% 0,61% 16%,90% 10%,81% 37%,100% 56%,74% 66%,79% 100%,53% 81%,28% 100%,30% 71%,0 60%,24% 43%,14% 17%);image-rendering:pixelated}.battle-sprite:after{content:'••';white-space:pre;position:absolute;left:42px;top:37px;color:#ded796;letter-spacing:8px;font-size:7px}.battle-log{min-height:32px;border-top:1px solid #343a32;border-bottom:1px solid #343a32;display:flex;align-items:center;color:#c1c8b7;font:10px var(--mono);padding:0 9px}.battle-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;padding-top:12px}.active-creature{display:grid;grid-template-columns:37px auto;grid-template-rows:auto auto;align-items:center;column-gap:9px;min-width:170px}.mini-sprite{grid-row:span 2;width:35px;height:35px;border:1px solid #5b694b;background:radial-gradient(circle,#536444 0%,#1d261d 68%);display:grid;place-items:center;color:#d7e9ae}.active-creature>div:nth-child(2){font:12px var(--serif);color:#e0e2d5}.active-creature small{display:block;color:#9ba391;font:8px var(--mono);margin-top:3px}.active-creature small b{color:#c3d69d;font-weight:400}.ally-track{grid-column:2;height:3px;width:100%;margin-top:5px}.battle-actions{display:flex;gap:6px}.battle-actions button{background:#222823;border:1px solid #414b3d;color:#d7daca;padding:8px 10px;font:9px var(--mono);cursor:pointer;white-space:nowrap}.battle-actions button:hover{background:#303a2e;border-color:#94ab74}.battle-actions button span{color:#9bb27b;margin-right:4px}.battle-actions button em{color:#93a480;font-style:normal}.battle-actions button:disabled{opacity:.42;cursor:not-allowed}.evolution{position:absolute;z-index:5;inset:0;background:#111610f5;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.evo-symbol{font-size:47px;color:#d5e8a9;text-shadow:0 0 30px #b2cf7d;margin-bottom:12px}.evolution h2{font:700 28px var(--serif);margin:8px 0;color:#e5e6d7}.evolution p{font:11px var(--mono);color:#a4ae9a;margin:0 0 20px}.evolution button{padding:10px 14px}.mobile-controls{display:none}
@media(max-width:850px){body{padding:0;background:var(--ink)}.game-shell{border:0}.game-layout{grid-template-columns:minmax(0,1fr) 245px}.viewport-wrap{padding:14px 14px 0}.sidebar{padding:17px 14px 12px}.companion-portrait{width:65px;height:77px}.battle-actions button{padding:7px 6px;font-size:8px}.active-creature{min-width:132px}.underbar{font-size:8px}}
@media(max-width:650px){body{padding:0;display:block}.game-shell{min-height:100dvh;display:flex;flex-direction:column}.topbar{height:56px;padding:0 13px}.chapter{font-size:8px;letter-spacing:.6px;gap:5px}.sound-toggle{padding:6px}.brand strong{font-size:11px}.game-layout{display:flex;flex-direction:column}.viewport-wrap{padding:8px 8px 0}.viewport{aspect-ratio:4/3}.underbar{height:29px;font-size:7px;letter-spacing:.3px}.underbar>span:nth-child(2){display:none}.keycap{margin-left:4px}.location-label{top:9px;left:9px}.objective{top:8px;right:8px;padding:5px 6px;gap:5px}.objective b{font-size:7px}.objective small{font-size:6px}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:0 12px;padding:10px 12px;border-left:0;border-top:1px solid var(--line)}.sidebar>.side-heading:first-child{grid-column:1}.companion-card{grid-column:1;grid-row:2;margin:9px 0 7px}.sidebar>.side-divider:nth-of-type(3){display:none}.sidebar>.side-heading:nth-of-type(4){grid-column:2;grid-row:1}.kit-row{grid-column:2;margin-top:8px}.kit-row+.kit-row{margin-top:6px}.sidebar>.side-divider:nth-of-type(7),.sidebar>.side-heading:nth-of-type(8),.note-card,.sidebar-footer{display:none}.companion-portrait{height:56px;width:52px}.companion-info h2{font-size:16px;margin:2px 0 4px}.companion-info .side-hp{margin-top:5px}.level-line{font-size:8px}.chapter{margin-right:auto;margin-left:16px}.topbar{gap:8px}.intro-card{padding:8%}.intro-card h1{font-size:31px}.intro-card p{font-size:10px}.battle{padding:10px 11px}.enemy-card{padding:8px 6%;}.battle-sprite{transform:scale(.8);margin-right:5px}.enemy-copy strong{font-size:20px}.enemy-copy .health-track{width:120px}.battle-log{font-size:8px;min-height:29px}.battle-bottom{padding-top:8px;gap:6px}.battle-actions{gap:4px}.battle-actions button{padding:7px 5px;font-size:7px}.battle-actions button span{display:none}.active-creature{min-width:105px;grid-template-columns:29px auto;column-gap:6px}.mini-sprite{width:28px;height:29px}.active-creature>div:nth-child(2){font-size:10px}.active-creature small{font-size:7px}.mobile-controls{display:flex;align-items:center;justify-content:space-between;padding:8px 20px 10px;min-height:84px}.dpad{width:114px;height:74px;position:relative}.dpad button{position:absolute;width:34px;height:30px;background:#1b211c;border:1px solid #384336;color:#c7d4b1;font-size:12px;touch-action:none}.dpad button[data-dir=up]{left:40px;top:0}.dpad button[data-dir=left]{left:4px;top:32px}.dpad button[data-dir=down]{left:40px;top:32px}.dpad button[data-dir=right]{left:76px;top:32px}.touch-action{background:#20281f;border:1px solid #60734d;color:#d7e4c2;padding:11px 15px;font:9px var(--mono);letter-spacing:1px;touch-action:none}.touch-action span{color:#98b779;margin-left:8px}footer{height:31px;padding:0 11px;font-size:7px}.sidebar-footer{display:none}}
@media(max-width:380px){.objective>span:nth-child(2){max-width:90px}.objective i{display:none}.chapter{margin-left:5px}.chapter span,.chapter i{display:none}.battle-actions button{padding:7px 4px}.battle-actions button em{font-size:7px}}

(()=>{
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const W=canvas.width,H=canvas.height,T=16,MW=42,MH=30;
const ui={battle:document.getElementById('battle'),intro:document.getElementById('intro'),evolution:document.getElementById('evolution'),toast:document.getElementById('toast'),log:document.getElementById('battleLog')};
let map=[],decor=[],enemies=[],gameStarted=false,inBattle=false,turnLock=false,toastTimer,moveTimer=0,steps=0,dialogueDone=false,sound=true,gameOver=false;
const keys={};
const state={x:7,y:8,face:'down',sigils:[],snare:3,tonic:2,active:0,party:[{name:'Mothkin',species:'Mothkin',level:1,xp:0,hp:24,max:24,atk:6,kind:'moth'}],enemy:null,place:'THE GLOAMWOOD',won:false};
const sigilSpots=[{x:12,y:8,name:'The First Sigil',hint:'It hums in your palm.'},{x:31,y:19,name:'The Drowned Sigil',hint:'Cold as a stone from the river.'},{x:7,y:24,name:'The Thorn Sigil',hint:'A thorn curls around its light.'}];
const altar={x:22,y:7};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function rand(n){return Math.floor(Math.random()*n)}
function tile(x,y,v){if(x>=0&&y>=0&&x<MW&&y<MH)map[y][x]=v}
function path(x1,y1,x2,y2){let x=x1,y=y1;while(x!==x2){tile(x,y,1);tile(x,y+1,1);x+=Math.sign(x2-x)}while(y!==y2){tile(x,y,1);tile(x+1,y,1);y+=Math.sign(y2-y)}}
function buildMap(){map=Array.from({length:MH},(_,y)=>Array.from({length:MW},(_,x)=>x===0||y===0||x===MW-1||y===MH-1?3:0));path(7,8,7,12);path(7,12,17,12);path(17,12,17,7);path(17,7,24,7);path(17,12,26,12);path(26,12,31,19);path(26,12,34,11);path(7,12,7,24);path(7,24,13,24);path(13,24,19,20);path(19,20,31,19);path(31,19,36,23);path(22,7,22,4);for(let x=19;x<26;x++){for(let y=4;y<10;y++)if((x===19||x===25||y===4||y===9)&&!(x===22&&y===4))tile(x,y,2)}
 // A broken cart, bog pools and old grave stones.
 for(const [x,y] of [[4,10],[13,5],[35,7],[20,24],[9,17],[34,25],[28,5],[3,20]])decor.push({x,y,type:'stone'});
 for(const [x,y] of [[26,17],[27,17],[26,18],[5,26],[6,26],[33,7],[34,7]])tile(x,y,4);
 // Reproducible thickets; keep routes, clearings, landmarks and the player start open.
 let seed=8129;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 for(let y=2;y<MH-2;y++)for(let x=2;x<MW-2;x++){if(map[y][x]!==0||rnd()>.22)continue;let near=false;for(let yy=Math.max(0,y-1);yy<=Math.min(MH-1,y+1);yy++)for(let xx=Math.max(0,x-1);xx<=Math.min(MW-1,x+1);xx++)if(map[yy][xx]===1||map[yy][xx]===2)near=true;if(!near&&!(x<10&&y<11)&&!(x>19&&x<26&&y<10))map[y][x]=3}
 for(let y=1;y<MH-1;y++)for(let x=1;x<MW-1;x++)if(map[y][x]===0&&rnd()<.105)map[y][x]=5;
}
function active(){return state.party[state.active]||state.party[0]}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function say(text){ui.log.textContent=text}
function save(){try{localStorage.setItem('hollowmere-save',JSON.stringify(state));document.getElementById('saveStatus').textContent='AUTOSAVED'}catch(e){}}
function load(){try{const s=JSON.parse(localStorage.getItem('hollowmere-save'));if(s&&s.party?.length){Object.assign(state,s);state.enemy=null}}catch(e){}}
function updateUI(){const a=active(),pct=a.max?Math.max(0,a.hp/a.max*100):0;document.getElementById('sideAllyName').textContent=a.name;document.getElementById('allyLevel').textContent=String(a.level).padStart(2,'0');document.getElementById('sideHealth').style.width=pct+'%';document.getElementById('sideHpText').textContent=`${a.hp} / ${a.max} VIT`;document.getElementById('allyName').textContent=a.name;document.getElementById('allyHpText').textContent=`${a.hp} / ${a.max}`;document.getElementById('allyHealth').style.width=pct+'%';document.getElementById('kitSnares').textContent=String(state.snare).padStart(2,'0');document.getElementById('kitTonics').textContent=String(state.tonic).padStart(2,'0');document.getElementById('snareCount').textContent='× '+state.snare;document.getElementById('itemCount').textContent=String(state.snare+state.tonic).padStart(2,'0');document.getElementById('sigilCount').textContent=`${state.sigils.length} / 3`;document.getElementById('objectiveText').textContent=state.sigils.length===3?'Reach the old stone altar':'Find the three lost sigils';document.getElementById('coord').textContent=`X ${String(state.x).padStart(2,'0')} · Y ${String(state.y).padStart(2,'0')}`;document.getElementById('allyMood').textContent=a.species==='Mothkin'&&a.level>=3?'AWAKENED':a.hp<a.max/3?'UNEASY':'RESTLESS';document.getElementById('battlePlace').textContent=state.place;}
function passable(x,y){return x>=0&&y>=0&&x<MW&&y<MH&&map[y][x]!==3&&map[y][x]!==4&&map[y][x]!==2}
function attemptMove(dx,dy){if(!gameStarted||inBattle||ui.evolution.classList.contains('hidden')===false||gameOver)return;let nx=state.x+dx,ny=state.y+dy;if(!passable(nx,ny))return;state.x=nx;state.y=ny;state.face=dx<0?'left':dx>0?'right':dy<0?'up':'down';steps++;if(map[ny][nx]===5&&Math.random()<.17){startBattle();return}if(steps%5===0&&Math.random()<.24){startBattle();return}if(steps%7===0){state.tonic=Math.min(5,state.tonic+(Math.random()<.25?1:0));updateUI()}checkPlace();updateUI();save()}
function checkPlace(){if(state.x<14&&state.y<13)state.place='THE OLD ROAD';else if(state.x>=18&&state.x<=26&&state.y<11)state.place='WITCHLIGHT RUINS';else if(state.x>28&&state.y>14)state.place='THE DROWNED PATH';else if(state.y>20)state.place='THORNFALL';else state.place='THE GLOAMWOOD';document.getElementById('locationName').textContent=state.place;document.getElementById('locationSub').textContent=state.place==='WITCHLIGHT RUINS'?'THE ALTAR KEEPS ITS TEETH':state.place==='THE DROWNED PATH'?'DON’T FOLLOW THE BELLS':state.place==='THORNFALL'?'BRAMBLES BENEATH THE MOON':'THE OLD ROAD'}
function interact(){if(!gameStarted){begin();return}if(inBattle)return;let near=(obj)=>Math.abs(state.x-obj.x)+Math.abs(state.y-obj.y)<=1;
 const sig=sigilSpots.find((s,i)=>near(s)&&!state.sigils.includes(i));if(sig){const i=sigilSpots.indexOf(sig);state.sigils.push(i);showToast(`${sig.name} recovered. ${sig.hint}`);say?.('');updateUI();save();return}
